/* =========================================================
   ARCHLENS — MAIN FRONTEND APPLICATION
   Features:
   1. Backend status
   2. Repository selection
   3. Architecture graph
   4. Component details
   5. Repository-aware RAG Q&A
   6. Change-impact analysis
   7. Architecture Intelligence Center
========================================================= */

const API_BASE_URL = "http://127.0.0.1:8000";

let architectureData = null;
let cy = null;
let selectedComponent = null;
let currentRepository = null;


/* =========================================================
   HELPERS
========================================================= */

function getElement(...ids) {
    for (const id of ids) {
        const element = document.getElementById(id);

        if (element) {
            return element;
        }
    }

    return null;
}


function escapeHtml(value) {
    const div = document.createElement("div");
    div.textContent = String(value ?? "");
    return div.innerHTML;
}


function setText(ids, value) {
    const element = getElement(...ids);

    if (element) {
        element.textContent = String(value ?? "");
    }
}


function setStatus(message) {
    const element = getElement("dashboardStatus");

    if (element) {
        element.textContent = message;
    }
}


async function apiRequest(path, options = {}) {
    const response = await fetch(`${API_BASE_URL}${path}`, {
        ...options,
        headers: {
            ...(options.body ? { "Content-Type": "application/json" } : {}),
            ...(options.headers || {})
        }
    });

    const contentType = response.headers.get("content-type") || "";

    let data;

    if (contentType.includes("application/json")) {
        data = await response.json();
    } else {
        data = await response.text();
    }

    if (!response.ok) {
        const message =
            typeof data === "object"
                ? data.detail || data.message
                : data;

        throw new Error(message || `HTTP ${response.status}`);
    }

    return data;
}


/* =========================================================
   BACKEND STATUS
========================================================= */

async function checkBackend() {
    const status = getElement("status");

    try {
        const data = await apiRequest("/");

        if (status) {
            status.innerHTML = `
                <span class="status-dot"></span>
                Backend Connected
            `;
        }

        console.log("Backend:", data);

    } catch (error) {
        console.error("Backend connection failed:", error);

        if (status) {
            status.innerHTML = `
                <span class="status-dot"
                      style="background:#ef4444"></span>
                Backend Offline
            `;
        }
    }
}


