            fit: true,
            spacingFactor: 1.5,
            padding: 80,
            nodeRepulsion: 8000,
            idealEdgeLength: 150



        },

        minZoom: 0.1,
        maxZoom: 3,
        wheelSensitivity: 0.2
    });

    cy.on("tap", "node", (event) => {
        const data = event.target.data();

        const original = data.original || {};

        selectedComponent = {
            id: String(data.id),
            label: data.label,
            type: data.type,
            file: data.file,
            original
        };

        showComponentDetails(original.id !== undefined
            ? original
            : {
                id: data.id,
                label: data.label,
                type: data.type,
                file: data.file
            }
        );

        const impactButton = getElement("impactButton");

        if (impactButton) {
            impactButton.disabled = false;
        }
    });

    cy.on("tap", (event) => {
        if (event.target === cy) {
            selectedComponent = null;
        }
    });

    // Allow Cytoscape to size itself correctly.
    requestAnimationFrame(() => {
        if (cy) {
            cy.resize();
            cy.fit(undefined, 40);
        }
    });
}


