def get_repositories():
    repositories = []

    for file in BASE_DIR.glob("architecture_graph_*.json"):
        name = file.stem.replace(
            "architecture_graph_",
            ""
        )
        repositories.append(name)

    repositories.sort()

    return {
        "repositories": repositories
    }

